html:
{% set ctx = get_fee_certificate_context(doc.name) %}
{% set settings = ctx.settings %}
{% set student = ctx.student %}
{% set table = ctx.table %}
{% set is_multi_year = doc.certificate_mode == "Multi Year" %}

<!DOCTYPE html>
<html>
<head>
	<meta charset="UTF-8">
	<style>
		@page {
			size: A4;
			margin: 15mm;
		}

		body {
			font-family: Georgia, "Times New Roman", serif;
			font-size: 10.5pt;
			line-height: 1.4;
			color: #000;
		}

		.header {
			display: flex;
			align-items: center;
			border-bottom: 2px solid #6d1b3a;
			padding-bottom: 8px;
			margin-bottom: 10px;
		}

		.header img {
			height: 60px;
			margin-right: 16px;
			flex-shrink: 0;
		}

		.header h1 {
			margin: 0;
			font-size: 15pt;
			color: #6d1b3a;
		}

		.header .address {
			font-size: 8.5pt;
			margin-top: 2px;
		}

		.date-line {
			text-align: right;
			margin-bottom: 10px;
		}

		.title {
			text-align: center;
			text-decoration: underline;
			font-weight: bold;
			font-size: 12pt;
			margin-bottom: 12px;
		}

		.body-text {
			text-align: justify;
			margin-bottom: 10px;
		}

		table.fee-table {
			width: 100%;
			border-collapse: collapse;
			margin-bottom: 10px;
		}

		table.fee-table th, table.fee-table td {
			border: 1px solid #000;
			padding: 5px 8px;
			font-size: 10pt;
		}

		table.fee-table th {
			text-align: center;
			background-color: #f2f2f2;
		}

		table.fee-table td.amount {
			text-align: right;
		}

		table.fee-table td.sl {
			text-align: center;
		}

		table.fee-table tr.total-row td, table.fee-table tr.net-row td {
			font-weight: bold;
		}

		.note {
			font-size: 9pt;
			font-style: italic;
			margin-bottom: 10px;
		}

		.bank-details {
			margin-bottom: 14px;
		}

		.signature-block {
			margin-top: 40px;
			text-align: right;
		}

		.signature-block .sign-col img {
			height: 50px;
			display: block;
			margin-left: auto;
			margin-bottom: 4px;
		}

		.signature-block .seal {
			height: 70px;
			display: block;
			margin-left: auto;
			margin-top: 6px;
		}

		.signature-block .designation {
			font-weight: bold;
		}

		.footer {
			margin-top: 30px;
			border-top: 1px solid #000;
			padding-top: 6px;
			font-size: 8pt;
			text-align: center;
		}
	</style>
</head>
<body>
	<div class="header">
		{% if settings.institute_logo %}<img src="data:image/png;base64,{{ get_file_b64(settings.institute_logo) }}">{% endif %}
		<div>
			<h1>{{ settings.institute_name or "" }}</h1>
			<div class="address">{{ settings.institute_address or "" }}</div>
			<div class="address">
				{%- set contact_parts = [] -%}
				{%- if settings.institute_phone -%}{%- set _ = contact_parts.append("Telephone: " ~ settings.institute_phone) -%}{%- endif -%}
				{%- if settings.institute_website -%}{%- set _ = contact_parts.append("Website: " ~ settings.institute_website) -%}{%- endif -%}
				{%- if settings.institute_email -%}{%- set _ = contact_parts.append("Email: " ~ settings.institute_email) -%}{%- endif -%}
				{{ contact_parts|join("  |  ") }}
			</div>
		</div>
	</div>

	<div class="date-line">{{ ctx.generation_date }}</div>

	<div class="title">FEE CERTIFICATE</div>

	{% if is_multi_year %}
	<div class="body-text">
		This is to certify that <strong>{{ student.full_name }}</strong> (Student ID &ndash; <strong>{{ student.registration_id }}</strong>)
		is studying in {{ ctx.current_year.ordinal_year }} year {{ student.programme }} programme during the Academic Year (AY)
		{{ ctx.current_year.academic_year }} in this University and {{ ctx.summary_sentence }}.
	</div>
	<div class="body-text">
		Year wise fee structure for {{ student.programme }} programme shown below.
	</div>
	{% else %}
	<div class="body-text">
		This is to certify that <strong>{{ student.full_name }}</strong> (Student ID &ndash; <strong>{{ student.registration_id }}</strong>)
		is studying in {{ ctx.current_year.ordinal_year }} year {{ student.programme }} programme during the Academic Year (AY)
		{{ ctx.current_year.academic_year }} in this University and {{ ctx.summary_sentence }}.
	</div>
	{% endif %}

	<table class="fee-table">
		<thead>
			<tr>
				<th style="width: 8%;">Sl. No.</th>
				<th>Particulars</th>
				{% for label in table.year_labels %}
				<th>{{ label }}</th>
				{% endfor %}
			</tr>
		</thead>
		<tbody>
			{% for row in table.rows %}
			<tr>
				<td class="sl">{{ loop.index }}</td>
				<td>{{ row.particulars }}</td>
				{% for amount in row.amounts %}
				<td class="amount">{{ amount }}</td>
				{% endfor %}
			</tr>
			{% endfor %}
			<tr class="total-row">
				<td colspan="2">{{ "Total Course Fee" if table.show_scholarship_row else "Total Fee Payable" }}</td>
				{% for amount in table.total_row %}
				<td class="amount">{{ amount }}</td>
				{% endfor %}
			</tr>
			{% if table.show_scholarship_row %}
			<tr>
				<td colspan="2">Less: University Scholarship</td>
				{% for amount in table.scholarship_row %}
				<td class="amount">({{ amount }})</td>
				{% endfor %}
			</tr>
			<tr class="net-row">
				<td colspan="2">Total Fee Payable</td>
				{% for amount in table.net_row %}
				<td class="amount">{{ amount }}</td>
				{% endfor %}
			</tr>
			{% endif %}
		</tbody>
	</table>

	{% if is_multi_year %}
	<div class="note">
		Note: The fees / charges are provisional and subject to ratification &amp; revision by the governing authorities of the University.
	</div>
	{% endif %}

	{% if doc.include_bank_details %}
	<div class="bank-details">
		The amount sanctioned towards fees due may be remitted to the University bank account provided below:<br>
		Name - {{ settings.bank_account_name or settings.institute_name }}, A/c No &ndash; {{ settings.bank_account_no }},
		IFSC - {{ settings.bank_ifsc_code }}, Bank &amp; branch - {{ settings.bank_branch }}
	</div>
	{% endif %}

	<div class="signature-block">
		<div class="sign-col">
			{% if settings.cfo_signature %}<img src="data:image/png;base64,{{ get_file_b64(settings.cfo_signature) }}">{% endif %}
			<div class="designation">{{ settings.cfo_designation or "Chief Finance Officer" }}</div>
			{% if settings.seal_image %}<img class="seal" src="data:image/png;base64,{{ get_file_b64(settings.seal_image) }}">{% endif %}
		</div>
	</div>

	<div class="footer">{{ settings.footer_note or "" }}</div>
</body>
</html>
